//go:build linux

// Package bootid reads the Linux kernel boot identifier.
package bootid

import (
	"errors"
	"os"
	"strings"
)

var path = "/proc/sys/kernel/random/boot_id"

// Get returns the identifier generated by the kernel for the current boot.
func Get() (string, error) {
	value, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	id := strings.TrimSpace(string(value))
	if id == "" {
		return "", errors.New("empty boot ID")
	}
	return id, nil
}
